diff --git a/Sources/SwiftJXLCore/Codec/ScalarMap.swift b/Sources/SwiftJXLCore/Codec/ScalarMap.swift
index 3dd01d7..8edba42 100644
--- a/Sources/SwiftJXLCore/Codec/ScalarMap.swift
+++ b/Sources/SwiftJXLCore/Codec/ScalarMap.swift
@@ -27,18 +27,30 @@ func parallelMap<T: Sendable>(_ count: Int, _ work: @Sendable (Int) throws -> T)
         MemoryLayout<Result<T, any Error>?>.stride, MemoryLayout<T>.stride)
     try context.budget.reserveWorkspace(ScalarOperationBudget.sum(128,
         ScalarOperationBudget.product(count, ScalarOperationBudget.product(elementBytes, 2))))
-    let results = Mutex([Result<T, any Error>?](repeating: nil, count: count))
+    let state = Mutex((nextIndex: workers,
+                       results: [Result<T, any Error>?](repeating: nil, count: count)))
     let audit = ScalarStorageAudit.current
     DispatchQueue.concurrentPerform(iterations: workers) { worker in
         ScalarMapScope.$isWorker.withValue(true) {
             ScalarEncodingWork.$current.withValue(context) {
                 ScalarStorageAudit.$current.withValue(audit) {
-                    for index in stride(from: worker, to: count, by: workers) {
+                    var index = worker
+                    while index < count {
                         let result = Result {
                             try context.checkpoint()
                             return try work(index)
                         }
-                        results.withLock { $0[index] = result }
+                        // Publish and claim together: faster workers take the
+                        // next unassigned chunk instead of waiting for a fixed
+                        // stripe. Callbacks run outside the lock; each index is
+                        // claimed once and results retain their input order.
+                        index = state.withLock {
+                            $0.results[index] = result
+                            guard $0.nextIndex < count else { return count }
+                            let next = $0.nextIndex
+                            $0.nextIndex += 1
+                            return next
+                        }
                     }
                 }
             }
@@ -47,7 +59,7 @@ func parallelMap<T: Sendable>(_ count: Int, _ work: @Sendable (Int) throws -> T)
     try context.checkpoint()
     var output: [T] = []
     output.reserveCapacity(count)
-    for result in results.withLock({ $0 }) {
+    for result in state.withLock({ $0.results }) {
         // concurrentPerform has joined every assigned index. Keep this guard
         // rather than an input-dependent force unwrap at the result boundary.
         guard let result else { throw ScalarModularError.invalidInput("Missing encoder worker result") }
diff --git a/Tests/SwiftJXLCoreTests/ModularParallelTests.swift b/Tests/SwiftJXLCoreTests/ModularParallelTests.swift
index a4133dc..b7dabc5 100644
--- a/Tests/SwiftJXLCoreTests/ModularParallelTests.swift
+++ b/Tests/SwiftJXLCoreTests/ModularParallelTests.swift
@@ -34,13 +34,13 @@ struct ModularParallelTests {
         }
     }

-    @Test(arguments: [1, 2, 8, 100])
-    func boundedNestedWorkersPropagateContextsAndReturnOrderedResults(_ workers: Int) throws {
+    @Test(arguments: [1, 2, 8, 100], [0, 1, 7, 20, 23])
+    func boundedNestedWorkersPropagateContextsAndReturnOrderedResults(_ workers: Int, _ count: Int) throws {
         let b = try budget(workers: workers), context = ScalarEncodingWork(budget: b, writerByteLimit: 1024)
         let audit = ScalarStorageAudit(), counts = Mutex(Counts())
         let results = try ScalarStorageAudit.$current.withValue(audit) {
             try ScalarEncodingWork.$current.withValue(context) {
-                try parallelMap(20) { index in
+                try parallelMap(count) { index in
                     try parallelMap(3) { nested -> Int in
                         counts.withLock {
                             $0.active += 1; $0.peak = max($0.peak, $0.active)
@@ -54,10 +54,10 @@ struct ModularParallelTests {
                 }
             }
         }
-        #expect(results.flatMap { $0 } == Array(0..<60))
+        #expect(results.flatMap { $0 } == Array(0..<(count * 3)))
         let snapshot = counts.withLock { $0 }
-        #expect(snapshot.active == 0 && snapshot.completed == 60 && snapshot.contextsMatch)
-        #expect(snapshot.peak >= 1 && snapshot.peak <= min(workers, 8))
+        #expect(snapshot.active == 0 && snapshot.completed == count * 3 && snapshot.contextsMatch)
+        #expect(snapshot.peak >= (count == 0 ? 0 : 1) && snapshot.peak <= min(count, min(workers, 8)))
         #expect(b.maximumWorkers == min(workers, 8))
     }
